const ccid = $('Webhook').first().json.headers['x-telnyx-call-control-id'];
const convs = $input.first().json.data || [];
const match = convs.find(c => c.metadata && c.metadata.call_control_id === ccid);
if (!match) { return []; }
return [{ json: { conversationId: match.id, phone: (match.metadata.telnyx_end_user_target || match.metadata.from || '') } }];

const phone = $('Match Conversation').first().json.phone;
const msgs = ($input.first().json.data || [])
  .filter(m => m.text && String(m.text).trim() !== '' && (m.role === 'user' || m.role === 'assistant') && !m.tool_calls)
  .sort((a,b) => new Date(a.created_at) - new Date(b.created_at));
const transcript = msgs.map(m => (m.role === 'user' ? 'Caller' : 'Agent') + ': ' + m.text).join('\n');
return [{ json: { phone, transcript: transcript || 'No conversation content' } }];

const extracted = $('Format Response').first().json.output || {};
const phone = $('Build Transcript').first().json.phone || '';

function isEmpty(v) { return v === null || v === undefined || v === '' || v === 0; }

const fieldOrder = ['Nationality','Age','Marital Status','Number of Children','Net Salary','Budget','Timeline','Mortgage Status','Property Type','Preferred Areas'];

// Pick most complete existing record (empty if brand-new caller)
const candidates = $input.all().map(i => i.json).filter(r => r && r.id);
let existing = null, best = -1;
for (const rec of candidates) {
  let s = 0;
  for (const f of fieldOrder) { if (!isEmpty(rec[f])) s++; }
  if (s > best) { best = s; existing = rec; }
}

const map = {
  'Nationality':'nationality',
  'Age':'age',
  'Marital Status':'maritalStatus',
  'Number of Children':'numberChildren',
  'Net Salary':'netSalary',
  'Budget':'budgetRange',
  'Timeline':'timeline',
  'Mortgage Status':'mortgageStatus',
  'Property Type':'propertyType',
  'Preferred Areas':'preferredAreas'
};

// Existing data wins; extraction only fills genuine blanks (prevents hallucination overwrite)
const fields = {};
for (const [airField, exKey] of Object.entries(map)) {
  const existingVal = existing ? existing[airField] : undefined;
  const exVal = extracted[exKey];
  fields[airField] = !isEmpty(existingVal) ? existingVal : (isEmpty(exVal) ? '' : exVal);
}

const qualifiedLead = (existing && existing['Qualified Lead'] === true) || extracted.qualifiedLead === true;

// Preserve existing source/stage; default for brand-new inbound callers
const originalSource = (existing && existing['Original Source']) || 'Inbound Call';
const pipelineStage = (existing && existing['Pipeline Stage']) || 'Qualifying';

return [{ json: {
  recordId: existing ? existing.id : '',
  found: Boolean(existing),
  phone,
  qualifiedLead,
  originalSource,
  pipelineStage,
  fields
}}];

